void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / max(iResolution.xy, vec2(1.0));
  vec4 source = vrchSampleSource0(uv);
  float confidence = vrchReadSignal(0);
  vec2 center = vec2(vrchReadSignal(1), vrchReadSignal(2));
  float aspect = iResolution.x / max(iResolution.y, 1.0);
  vec2 delta = (uv - center) * vec2(aspect, 1.0);
  float face = 1.0 - smoothstep(uParam_face_size * 0.72, uParam_face_size, length(delta));
  vec2 px = vec2(uParam_softness) / max(iResolution.xy, vec2(1.0));
  vec3 blur = source.rgb;
  blur += vrchSampleSource0(uv + vec2(px.x, 0.0)).rgb;
  blur += vrchSampleSource0(uv - vec2(px.x, 0.0)).rgb;
  blur += vrchSampleSource0(uv + vec2(0.0, px.y)).rgb;
  blur += vrchSampleSource0(uv - vec2(0.0, px.y)).rgb;
  blur *= 0.2;
  float luma = dot(blur, vec3(0.2126, 0.7152, 0.0722));
  vec3 treated = mix(blur, vec3(luma) * uParam_background_tint.rgb, uParam_desaturate);
  treated *= 1.0 - uParam_dim;
  float effectAmount = clamp(uParam_amount * confidence, 0.0, 1.0);
  vec3 color = mix(source.rgb, treated, effectAmount * (1.0 - face));
  float contour = vrchSampleSignalTexture(0, uv).a * uParam_contour * confidence;
  color += uParam_contour_color.rgb * contour * 0.35;
  fragColor = vec4(color, source.a);
}
